// Merge all data sources and build activity string
const today = new Date().toISOString().split('T')[0];

// --- GitHub commits ---
let githubItems = [];
try {
  const raw = $('GitHub: Get Commits (24h)').all();
  for (const item of raw) {
    const commits = Array.isArray(item.json) ? item.json : [];
    for (const commit of commits) {
      githubItems.push({
        source: 'GitHub',
        type: 'commit',
        id: commit.sha ? commit.sha.slice(0, 7) : 'unknown',
        title: commit.commit?.message?.split('\n')[0] || 'No message',
        author: commit.commit?.author?.name || 'Unknown',
        url: commit.html_url || '',
        timestamp: commit.commit?.author?.date || ''
      });
    }
  }
} catch(e) {
  githubItems = [{ source: 'GitHub', type: 'error', title: 'Could not fetch commits: ' + e.message }];
}

// --- Redmine issues ---
let redmineItems = [];
try {
  const raw = $('Redmine: Get Issues Today').all();
  for (const item of raw) {
    const issues = item.json?.issues || [];
    for (const issue of issues) {
      redmineItems.push({
        source: 'Redmine',
        type: 'issue',
        id: String(issue.id),
        title: issue.subject || 'No subject',
        status: issue.status?.name || 'Unknown',
        priority: issue.priority?.name || 'Normal',
        project: issue.project?.name || 'Unknown',
        updated: issue.updated_on || ''
      });
    }
  }
} catch(e) {
  redmineItems = [{ source: 'Redmine', type: 'error', title: 'Could not fetch issues: ' + e.message }];
}

// --- Slack messages ---
let slackItems = [];
try {
  const raw = $('Slack: Get Today\'s Messages').all();
  for (const item of raw) {
    const messages = Array.isArray(item.json) ? item.json : (item.json?.messages || []);
    for (const msg of messages) {
      if (!msg.bot_id && msg.text && msg.text.trim()) {
        slackItems.push({
          source: 'Slack',
          type: 'message',
          id: msg.ts || '',
          title: msg.text.slice(0, 200),
          user: msg.user || 'unknown',
          timestamp: msg.ts || ''
        });
      }
    }
  }
} catch(e) {
  slackItems = [{ source: 'Slack', type: 'error', title: 'Could not fetch messages: ' + e.message }];
}

// --- Gmail (optional) ---
let gmailItems = [];
try {
  const raw = $('Gmail: Get Recent Emails (Optional)').all();
  for (const item of raw) {
    const emails = Array.isArray(item.json) ? item.json : [];
    for (const email of emails) {
      gmailItems.push({
        source: 'Gmail',
        type: 'email',
        id: email.id || '',
        title: email.subject || '(no subject)',
        from: email.from || 'unknown',
        timestamp: email.date || ''
      });
    }
  }
} catch(e) {
  gmailItems = [];
}

// --- Deduplicate by id+source ---
const seen = new Set();
const allItems = [...githubItems, ...redmineItems, ...slackItems, ...gmailItems].filter(item => {
  const key = `${item.source}:${item.id}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

// --- Build formatted activity string ---
let activityText = `Activity summary for ${today}:\n\n`;

if (githubItems.length > 0) {
  activityText += `## GitHub Commits (last 24h):\n`;
  for (const c of githubItems) {
    activityText += `- [${c.id}] ${c.title} (by ${c.author})\n`;
  }
  activityText += '\n';
}

if (redmineItems.length > 0) {
  activityText += `## Redmine Issues (assigned to me, updated today):\n`;
  for (const i of redmineItems) {
    activityText += `- #${i.id} [${i.status}] ${i.title} (${i.project})\n`;
  }
  activityText += '\n';
}

if (slackItems.length > 0 && slackItems.length <= 10) {
  activityText += `## Slack Activity (today):\n`;
  for (const m of slackItems.slice(0, 10)) {
    activityText += `- ${m.title}\n`;
  }
  activityText += '\n';
}

if (gmailItems.length > 0) {
  activityText += `## Recent Emails:\n`;
  for (const e of gmailItems.slice(0, 5)) {
    activityText += `- ${e.title} (from: ${e.from})\n`;
  }
  activityText += '\n';
}

if (allItems.length === 0) {
  activityText += 'No activity found from any source. Please describe manually what you worked on.\n';
}

return [{
  json: {
    today,
    activityText,
    stats: {
      githubCommits: githubItems.length,
      redmineIssues: redmineItems.length,
      slackMessages: slackItems.length,
      gmailEmails: gmailItems.length
    }
  }
}];
